import { api } from '../../api/client.js';
import styles from './QrCodesPage.module.css';

// Owner view: one QR code per restaurant, generated by the backend.
export default function QrCodesPage({ restaurants }) {
  if (!restaurants.length) {
    return <p className={styles.empty}>Add a restaurant to see its QR code here.</p>;
  }

  return (
    <div className={styles.grid}>
      {restaurants.map((r) => {
        const src = api.restaurantQrUrl(r.id);
        return (
          <article key={r.id} className={styles.card}>
            <h3 className={styles.title}>{r.name}</h3>
            {r.address && <p className={styles.muted}>{r.address}</p>}
            <img className={styles.qr} src={src} alt={`QR code for ${r.name}`} />
            <a className={styles.download} href={src} download={`luxar-restaurant-${r.id}.png`}>
              Download PNG
            </a>
          </article>
        );
      })}
    </div>
  );
}
